-- Investment Products FAQ (Advisor Edition: Mutual Funds, Bonds, SIF, PMS, Insurance)
CREATE TABLE IF NOT EXISTS faqs (
  id         TEXT PRIMARY KEY,
  category   TEXT NOT NULL,
  section    TEXT NOT NULL,
  question   TEXT NOT NULL,
  answer     TEXT NOT NULL,
  sort       INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_faqs_cat ON faqs(category, sort);

INSERT OR IGNORE INTO faqs (id, category, section, question, answer, sort) VALUES
('mf-1', 'Mutual Funds', '1.1 Mutual Fund Basics', 'What is a mutual fund, and how does it work?', 'A mutual fund pools money from many investors and invests it in a portfolio of securities, managed by a professional fund manager. Each investor owns units in proportion to the money invested, and gains or losses are shared in that proportion.', 1),
('mf-2', 'Mutual Funds', '1.1 Mutual Fund Basics', 'What are the different types of mutual funds available in India?', 'By asset class: equity, debt, hybrid and solution-oriented funds, plus other schemes such as index funds, ETFs and Funds of Funds. By structure: open-ended, close-ended and interval funds. SEBI sets a standard categorisation so that funds with the same label follow similar rules.', 2),
('mf-3', 'Mutual Funds', '1.1 Mutual Fund Basics', 'How do mutual funds differ from stocks, fixed deposits, and bonds?', 'Stocks: you own a share of one company; risk is concentrated. Fixed deposits: a bank pays a fixed rate and value is stable. Bonds: a loan to one issuer paying a fixed coupon. A mutual fund gives built-in diversification and professional management across many stocks or bonds.', 3),
('mf-4', 'Mutual Funds', '1.1 Mutual Fund Basics', 'What is Net Asset Value (NAV), and how is it calculated?', 'NAV is the price of one unit. It equals the market value of all holdings, minus liabilities and expenses, divided by the number of units outstanding. For example, a fund with assets of ₹210 lakh, liabilities of ₹10 lakh and 10 lakh units has an NAV of ₹20. It is declared at the end of each business day.', 4),
('mf-5', 'Mutual Funds', '1.1 Mutual Fund Basics', 'What is Assets Under Management (AUM), and why is it important?', 'AUM is the total market value of money a fund or AMC manages. It shows the size of a fund. Very small funds can face higher cost ratios, and very large funds in the small-cap space may find it harder to trade without moving prices.', 5),
('mf-6', 'Mutual Funds', '1.1 Mutual Fund Basics', 'What is the difference between open-ended, close-ended, and interval mutual funds?', 'Open-ended funds allow purchase and redemption on any business day. Close-ended funds are bought during the launch offer and redeemed only at maturity (they may be listed on an exchange). Interval funds open for transactions only during specified intervals.', 6),
('mf-7', 'Mutual Funds', '1.1 Mutual Fund Basics', 'What are equity, debt, hybrid, and solution-oriented mutual funds?', 'Equity funds invest mainly in shares for growth. Debt funds invest in bonds and money-market instruments for income and stability. Hybrid funds mix equity and debt (and sometimes gold). Solution-oriented funds, such as retirement and children''s funds, carry a lock-in of about five years or until a milestone.', 7),
('mf-8', 'Mutual Funds', '1.1 Mutual Fund Basics', 'What is the role of an Asset Management Company (AMC) in managing mutual funds?', 'The AMC manages the fund''s investments, appoints the fund managers and research team, handles investor servicing, and must follow SEBI rules and the trustees'' oversight.', 8),
('mf-9', 'Mutual Funds', '1.1 Mutual Fund Basics', 'Which regulatory authority governs mutual funds in India?', 'The Securities and Exchange Board of India (SEBI). It sets rules on categorisation, disclosures, expenses and investor protection.', 9),
('mf-10', 'Mutual Funds', '1.1 Mutual Fund Basics', 'Who are the key participants in the mutual fund ecosystem?', 'Sponsor (sets up the fund), Trustees (protect investors'' interests), AMC (manages the money), Custodian (holds securities), Registrar and Transfer Agent (maintains investor records), and Distributors or advisors.', 10),
('mf-11', 'Mutual Funds', '1.2 Investment Concepts', 'What is a Systematic Investment Plan (SIP), and how does it work?', 'An SIP invests a fixed amount at regular intervals, usually monthly, through an auto-debit from the bank account. Each instalment buys units at that day''s NAV.', 11),
('mf-12', 'Mutual Funds', '1.2 Investment Concepts', 'What is the difference between SIP, lump-sum investment, and Systematic Transfer Plan (STP)?', 'SIP spreads fresh money over time. A lump sum invests the full amount at once. STP moves money from one fund (often a liquid or debt fund) into another in instalments.', 12),
('mf-13', 'Mutual Funds', '1.2 Investment Concepts', 'What is a Systematic Withdrawal Plan (SWP), and who should consider investing through it?', 'An SWP pays a fixed amount from your holdings at regular intervals. It suits retirees or anyone needing regular cash flow while the rest of the money stays invested.', 13),
('mf-14', 'Mutual Funds', '1.2 Investment Concepts', 'What is the power of compounding, and how does it benefit mutual fund investors?', 'Returns earn further returns over time, so the longer the money stays invested, the faster it grows. For example, ₹1 lakh at 12% a year becomes about ₹3.1 lakh in 10 years and about ₹9.6 lakh in 20 years (illustrative, not guaranteed).', 14),
('mf-15', 'Mutual Funds', '1.2 Investment Concepts', 'What is rupee cost averaging, and how does it work in SIP investments?', 'Because an SIP invests a fixed amount each month, you buy more units when prices are low and fewer when prices are high. This lowers the average cost per unit over time and removes the need to time the market.', 15),
('mf-16', 'Mutual Funds', '1.3 Fund Selection & Evaluation', 'How should a financial advisor select the right mutual fund scheme for an investor?', 'Start with the investor''s goal, time horizon and risk tolerance. Then choose the category, shortlist funds within it, and compare them on consistency of performance, risk, costs and the fund house''s process.', 16),
('mf-17', 'Mutual Funds', '1.3 Fund Selection & Evaluation', 'What is Compound Annual Growth Rate (CAGR), and how is it calculated?', 'CAGR is the steady yearly rate that takes an investment from its starting value to its ending value. Formula: (Ending value ÷ Starting value)^(1 ÷ years) - 1. For example, ₹1 lakh growing to ₹1.46 lakh in 4 years is about 10% CAGR.', 17),
('mf-18', 'Mutual Funds', '1.3 Fund Selection & Evaluation', 'What are rolling returns, and why are they important when evaluating mutual funds?', 'Rolling returns measure returns over many overlapping periods (for example, every 3-year window across 10 years). They show how consistent a fund has been, rather than depending on one start and end date.', 18),
('mf-19', 'Mutual Funds', '1.3 Fund Selection & Evaluation', 'What is the difference between regular and direct mutual fund plans?', 'A direct plan is bought without a distributor and has a lower expense ratio. A regular plan is bought through a distributor, who is paid commission from the fund''s expenses, so the expense ratio is higher. Both hold the same portfolio.', 19),
('mf-20', 'Mutual Funds', '1.3 Fund Selection & Evaluation', 'What is the difference between Growth and IDCW options?', 'In the growth option, profits stay invested and compound in the NAV. In the IDCW option, the fund pays out part of the money from time to time, and NAV falls by the amount paid. IDCW is not a guaranteed income.', 20),
('mf-21', 'Mutual Funds', '1.4 Risk and Returns', 'What is the difference between standard deviation and beta in mutual fund risk measurement?', 'Standard deviation measures how widely a fund''s returns vary from its average. Beta measures how much the fund moves compared with the market: a beta of 1.2 means it tends to move 20% more than the market.', 21),
('mf-22', 'Mutual Funds', '1.4 Risk and Returns', 'What is the Sharpe ratio, and how does it help evaluate risk-adjusted returns?', 'It measures the return earned per unit of risk taken above a risk-free rate. A higher Sharpe ratio means better risk-adjusted performance, so it helps compare funds with different volatility.', 22),
('mf-23', 'Mutual Funds', '1.5 Equity Mutual Funds', 'What are large-cap, mid-cap, and small-cap mutual funds?', 'SEBI ranks companies by market capitalisation: top 100 are large-caps (min 80% in large-cap funds), 101st to 250th are mid-caps (min 65% in mid-cap funds), and 251st onwards are small-caps (min 65% in small-cap funds).', 23),
('mf-24', 'Mutual Funds', '1.5 Equity Mutual Funds', 'What is the difference between flexi-cap and multi-cap mutual funds?', 'A flexi-cap fund must hold at least 65% in equity with no limit on company size. A multi-cap fund must keep at least 25% each in large, mid and small-cap stocks, within an overall minimum of 75% in equity.', 24),
('mf-25', 'Mutual Funds', '1.5 Equity Mutual Funds', 'What is an Equity Linked Savings Scheme (ELSS), and what are its key features?', 'An ELSS is a diversified equity fund that qualifies for a deduction of up to ₹1.5 lakh a year under Section 80C (old tax regime only). It has a mandatory 3-year lock-in and invests at least 80% in equity.', 25),
('mf-26', 'Mutual Funds', '1.6 Debt Mutual Funds', 'What are overnight, liquid, and money market mutual funds, and how do they differ?', 'Overnight funds invest in securities maturing the next day. Liquid funds invest in instruments up to 91 days. Money market funds invest in instruments up to one year. Shorter maturity means lower risk.', 26),
('mf-27', 'Mutual Funds', '1.6 Debt Mutual Funds', 'What is duration in debt mutual funds, and why is it important?', 'Duration (in years) estimates how sensitive a fund''s price is to interest-rate changes. A fund with a duration of 5 years may fall about 5% if interest rates rise by 1 percentage point, and rise by about the same if rates fall.', 27),
('mf-28', 'Mutual Funds', '1.7 Taxation & Regulatory', 'How are capital gains from equity mutual funds taxed in India (FY 2026-27)?', 'For funds with at least 65% in Indian equity: gains on units held 12 months or less are short-term, taxed at 20%. Gains on units held more than 12 months are long-term, taxed at 12.5% on the amount above ₹1.25 lakh in a year.', 28),
('mf-29', 'Mutual Funds', '1.7 Taxation & Regulatory', 'How are returns from debt mutual funds taxed in India?', 'Funds with more than 65% in debt and money market (specified funds) bought on or after 1 April 2023 are taxed at the investor''s slab rate on all gains, regardless of holding period, with no indexation.', 29),
('mf-30', 'Mutual Funds', '1.8 Servicing & Transactions', 'How long does it typically take for investors to receive redemption proceeds?', 'Typically T+1 for liquid and overnight funds, and T+2 to T+3 business days for most equity and debt funds. Exact timelines are in each scheme''s documents.', 30),
('mf-31', 'Mutual Funds', '1.9 Portfolio Construction', 'How many mutual fund schemes should an investor ideally hold in their portfolio?', 'Usually 4 to 8 well-chosen funds are enough for most investors. Holding too many schemes adds overlap, complexity and monitoring effort without extra diversification.', 31),
('mf-32', 'Mutual Funds', '1.10 Advanced Concepts', 'What is the difference between alpha and beta in mutual fund performance evaluation?', 'Alpha is the return a fund earns above what its market exposure would predict, a measure of manager skill. Beta is the sensitivity to the market: how much the fund moves when the market moves.', 32),

('bd-1', 'Bonds', '2.1 Bond Basics', 'What is a bond, and how does it work?', 'A bond is a loan you give to a government or company. The issuer sets a face value, a coupon rate and a maturity date. Investors receive coupons at set intervals and get the face value back at maturity.', 40),
('bd-2', 'Bonds', '2.1 Bond Basics', 'What are the key differences between bonds and fixed deposits?', 'Issuer: bonds come from governments or companies; FDs from banks/NBFCs. Tradability: bonds can be sold in the market; FDs are broken with a penalty. Price: bond prices fluctuate before maturity; FD value is stable.', 41),
('bd-3', 'Bonds', '2.2 Returns & Interest', 'What is Yield to Maturity (YTM), and how is it calculated?', 'YTM is the total annual return if you buy at today''s price and hold to maturity, including all coupons and any gain or loss between purchase price and face value. It is the best single number for comparing bonds.', 42),
('bd-4', 'Bonds', '2.3 Risk and Safety', 'What is a credit rating, and why is it important when investing in bonds?', 'An independent opinion from a SEBI-registered agency (CRISIL, ICRA, CARE, India Ratings) on the issuer''s ability to pay on time. Ratings run from AAA (highest safety) to D (default).', 43),
('bd-5', 'Bonds', '2.4 Investment & Taxation', 'How can investors purchase bonds in India?', 'Through the RBI Retail Direct portal (government securities), the stock exchange with a demat account, SEBI-registered Online Bond Platform Providers, or public issues of NCDs. Minimums commonly start at ₹1,000 to ₹10,000.', 44),
('bd-6', 'Bonds', '2.4 Investment & Taxation', 'Are returns earned from bond investments taxable in India?', 'Yes. Coupon income is taxed at the investor''s slab rate. For listed bonds held more than 12 months, long-term capital gains are taxed at 12.5%; gains on unlisted bonds/debentures are generally taxed at the slab rate.', 45),
('bd-7', 'Bonds', '2.5 Investor Comparisons', 'What is the difference between secured and unsecured bonds?', 'Secured bonds are backed by specific assets that can be sold if the issuer fails. Unsecured bonds depend only on the issuer''s general ability to repay, so recoveries are weaker.', 46),
('bd-8', 'Bonds', '2.6 Practical Advisor Qs', 'Why do some bonds offer higher interest rates than others?', 'To compensate for higher risk: lower credit rating, longer maturity, lower liquidity, or no security. A very high yield is a warning sign rather than a bonus.', 47),

('sif-1', 'SIF', '3.1 SIF Basics', 'What is a Specialized Investment Fund (SIF), and how does it work?', 'A SIF is a mutual fund product regulated by SEBI that offers advanced strategies with more flexibility than regular schemes, including limited unhedged short positions through derivatives (up to 25% of net assets). It sits between mutual funds and PMS/AIFs.', 50),
('sif-2', 'SIF', '3.1 SIF Basics', 'What is the minimum investment amount required for SIFs?', '₹10 lakh per investor (PAN) across all strategies of one AMC''s SIF. SEBI-recognised Accredited Investors are exempt from the minimum. Holdings in regular mutual fund schemes do not count towards it.', 51),
('sif-3', 'SIF', '3.2 SIF Categories', 'What are the different categories and strategies available under SIFs?', 'Equity Long-Short, Equity Ex-Top 100 Long-Short, Sector Rotation Long-Short, Hybrid Long-Short, Debt Long-Short, Sectoral Debt Long-Short, and Active asset allocation strategies.', 52),
('sif-4', 'SIF', '3.3 Investment & Returns', 'Can SIFs take short positions in the financial market?', 'Yes, through derivatives (futures and options) and within a SEBI limit of 25% of net assets for unhedged shorts. Direct short selling of physical shares is not used.', 53),
('sif-5', 'SIF', '3.4 Risk and Taxation', 'How are returns from Specialized Investment Funds taxed in India?', 'SIF units are generally taxed under mutual fund rules according to the strategy''s equity exposure: equity-oriented strategies follow equity fund rates, and others follow non-equity fund rules.', 54),
('sif-6', 'SIF', '3.5 Comparisons', 'SIF vs. Portfolio Management Services (PMS): How do they differ?', 'SIF is a pooled unit scheme with a ₹10 lakh minimum, allows shorting via derivatives, and is taxed only on redemption. PMS holds individual securities in your demat account, requires ₹50 lakh minimum, allows customisation, and is taxed on each sale inside the portfolio.', 55),
('sif-7', 'SIF', '3.5 Comparisons', 'Can investors redeem their SIF investments at any time?', 'Redemption frequency depends on the strategy (daily, weekly or periodic), and a notice period of up to 15 working days may apply. If a redemption would take the holding below ₹10 lakh, only a full redemption is generally allowed.', 56),
('sif-8', 'SIF', '3.6 Practical Advisor Qs', 'How should SIFs be positioned within an investor''s overall portfolio?', 'As a satellite allocation alongside core mutual funds, sized to the investor''s risk profile. Avoid recommending it to first-time investors or for short-term needs.', 57),

('pms-1', 'PMS', '4.1 PMS Basics', 'What are Portfolio Management Services (PMS), and how do they work?', 'PMS is a personalised investment service where a SEBI-registered portfolio manager manages a portfolio of securities for a client. The securities are held in the client''s own demat account, not in a pool.', 60),
('pms-2', 'PMS', '4.1 PMS Basics', 'What is the minimum investment amount required for PMS?', '₹50 lakh per client, in cash, securities or a combination, as set by SEBI under the SEBI (Portfolio Managers) Regulations, 2020.', 61),
('pms-3', 'PMS', '4.1 PMS Basics', 'What are discretionary, non-discretionary, and advisory PMS?', 'In discretionary PMS, the manager decides and executes trades. In non-discretionary PMS, the manager suggests and the client approves each trade. In advisory PMS, the manager only advises and the client places the orders.', 62),
('pms-4', 'PMS', '4.2 Investment Strategies', 'What is a concentrated portfolio, and why do PMS strategies follow it?', 'A portfolio with a small number of holdings (for example, 15 to 30 stocks). Each stock has a larger weight, so a good idea can strongly boost returns, but performance can also differ sharply from the index in both directions.', 63),
('pms-5', 'PMS', '4.3 Investment & Returns', 'What is the difference between TWRR and XIRR in PMS?', 'TWRR (Time-Weighted Rate of Return) removes the effect of cash inflows/outflows to measure manager skill (mandated by SEBI for PMS reporting). XIRR (money-weighted return) reflects the client''s own experience including timing of deposits/withdrawals.', 64),
('pms-6', 'PMS', '4.4 Risk and Taxation', 'How are PMS investments and their returns taxed in India?', 'Because securities are in the client''s own name, every sale creates a capital gain or loss in the client''s hands (listed equity: 20% STCG <= 12m, 12.5% LTCG > ₹1.25 lakh). Dividends and interest are taxed at the slab rate.', 65),
('pms-7', 'PMS', '4.5 Comparisons', 'PMS vs. Mutual Funds vs. AIF: What are the key differences?', 'Mutual Funds: pooled, ₹500 minimum, taxed on redemption. PMS: individual demat, ₹50 lakh minimum, customisable, taxed on each sale. AIF: privately pooled vehicle, ₹1 crore minimum, Category III can use leverage.', 66),
('pms-8', 'PMS', '4.6 Practical Advisor Qs', 'How should advisors compare two different PMS providers?', 'Use TWRR returns net of fees over the same periods, compare against the same benchmark, inspect performance across market cycles and drawdowns, and review fee structures (fixed vs. profit-share with high-water mark).', 67),

('ins-1', 'Insurance', '5.1 Insurance Basics', 'What is the difference between life insurance and general insurance?', 'Life insurance covers death or survival over a long term and often pays a fixed sum assured. General insurance (health, motor, home, travel) covers specified losses over a short term (usually 1 year) and pays the actual loss up to a limit.', 70),
('ins-2', 'Insurance', '5.1 Insurance Basics', 'Who is a nominee in an insurance policy, and what are their responsibilities?', 'The person named by the policyholder to receive the claim money. A nominee receives the money on behalf of the legal heirs and must pass it on to those entitled under law or the will.', 71),
('ins-3', 'Insurance', '5.2 Life Insurance', 'What is the difference between term insurance and traditional life insurance plans?', 'Term insurance gives pure protection with high cover at low premium and no survival benefit. Traditional plans (endowment, money-back) bundle protection with low-return savings (often single digits) at much higher premiums.', 72),
('ins-4', 'Insurance', '5.2 Life Insurance', 'What are the key differences between ULIPs and mutual funds?', 'A ULIP bundles insurance and investment, has a 5-year lock-in and multiple charges (allocation, mortality, administration, fund management). A mutual fund is investment-only, has no mandatory lock-in (except ELSS), and generally lower, more transparent costs.', 73),
('ins-5', 'Insurance', '5.3 Health Insurance', 'What is the difference between individual health insurance and family floater plans?', 'An individual plan gives each person their own sum insured. A family floater has one sum insured shared by all members. Floaters cost less, while individual plans suit older members or those with health conditions.', 74),
('ins-6', 'Insurance', '5.3 Health Insurance', 'What is a waiting period in health insurance?', 'A period after buying the policy when certain claims are not payable: typically 30 days for most illnesses (except accidents), 1 to 3 years for specified procedures, and up to 3 years for pre-existing diseases.', 75),
('ins-7', 'Insurance', '5.3 Health Insurance', 'What is the difference between co-payment, deductible, and room rent limit?', 'Co-payment: fixed % of each claim you pay. Deductible: fixed amount you pay first each year. Room rent limit: cap on daily room charge; picking a costlier room can reduce other hospital charges proportionately.', 76),
('ins-8', 'Insurance', '5.4 Claims & Policy Benefits', 'What is the free-look period in an insurance policy?', 'A review window after receiving the policy: 15 days offline, 30 days for electronic or distance-mode policies. If you disagree with the terms, you can return the policy for a refund minus permitted deductions.', 77),
('ins-9', 'Insurance', '5.4 Claims & Policy Benefits', 'What are the common reasons for insurance claim rejection?', 'Non-disclosure or wrong disclosure of pre-existing conditions at purchase, claims during a waiting period, excluded conditions, a lapsed policy, missing documents or delayed intimation.', 78),
('ins-10', 'Insurance', '5.5 Taxation & Regulatory', 'How are life and health insurance premiums and maturity proceeds taxed?', 'Under the old tax regime, life premiums qualify up to ₹1.5 lakh under 80C and health premiums under 80D (no deduction in new regime). Death benefits are generally tax-free; maturity proceeds are exempt if premium is within prescribed limits (up to 10% of sum assured).', 79),
('ins-11', 'Insurance', '5.6 Practical Advisor Qs', 'How much life and health insurance coverage should an individual ideally have?', 'Life cover: 10 to 15 times annual income (or needs-based: loans + goals + family expenses minus existing assets). Health cover: ₹10 to ₹25 lakh base for a metro family, topped up with a super top-up plan.', 80),
('ins-12', 'Insurance', '5.6 Practical Advisor Qs', 'Why should insurance and investment needs be evaluated separately?', 'Protection and wealth creation have different purposes. Bundled products usually give lower cover and lower returns than combining pure term insurance with mutual funds.', 81);
